 private static final Map<String,JSONObject> BY_NAME=new LinkedHashMap<>();
 static {try{
  for(String json:RAW){JSONObject data=new JSONObject(json);
   if(BY_NAME.put(data.getString("id"),data)!=null)throw new IllegalStateException("XMM_SPELL_DUPLICATE");}
  if(BY_NAME.size()!=132)throw new IllegalStateException("XMM_SPELLCASTERS_MISSING");
 }catch(Exception e){throw new ExceptionInInitializerError(e);}}
 private Xmm2025SpellUsageIndex(){}
 public static JSONObject options(String monster)throws Exception {
  JSONObject data=BY_NAME.get(monster);
  if(data==null)return new JSONObject().put("resolved",false).put("reason","not_a_registered_spellcaster")
     .put("auto_rolls",false).put("auto_mutation_allowed",false);
  return new JSONObject(data.toString()).put("resolved",true)
     .put("source","XMM").put("source_blob_sha1",SOURCE_SHA)
     .put("source_commit",SOURCE_COMMIT).put("auto_rolls",false)
     .put("auto_mutation_allowed",false).put("spell_effects_applied",false);
 }
 /** Recognizes a spell and its exact source usage group. Counts and any recharge
  * condition are supplied by the game/DM; this never spends uses or casts a spell.
  */
 public static JSONObject check(JSONObject in)throws Exception{
  if(in==null)return blocked("missing_request");
  JSONObject data=BY_NAME.get(in.optString("monster"));
  if(data==null)return blocked("unknown_spellcasting_monster");
  String requested=in.optString("spell").trim();
  if(requested.isEmpty())return blocked("spell_required");
  JSONArray entries=data.getJSONArray("entries");
  for(int i=0;i<entries.length();i++){
   JSONObject entry=entries.getJSONObject(i);
   for(String usage:new String[]{"will","daily","restLong","legendary","recharge"}){
    JSONObject limits=entry.optJSONObject(usage);
    if("will".equals(usage)){
     JSONArray names=entry.optJSONArray("will");
     if(names!=null)for(int k=0;k<names.length();k++)
      if(requested.equalsIgnoreCase(names.getString(k)))
       return decision(data,entry,requested,"will",0,in);
    }else if(limits!=null){
     for(java.util.Iterator<String> usageKeys=limits.keys();usageKeys.hasNext();){
      String key=usageKeys.next();
      JSONArray names=limits.getJSONArray(key);
      for(int k=0;k<names.length();k++)
       if(requested.equalsIgnoreCase(names.getString(k)))
        return decision(data,entry,requested,usage,Integer.parseInt(key),in);
     }
    }
   }
  }
  return blocked("spell_not_in_source_spellcasting_options");
 }
 private static JSONObject decision(JSONObject row,JSONObject entry,String spell,String usage,int amount,JSONObject in)throws Exception {
  JSONObject out=new JSONObject().put("resolved",true).put("source","XMM")
    .put("monster",row.getString("id")).put("spell",spell).put("usage",usage)
    .put("entry",entry.getString("name")).put("display_as",entry.getString("display_as"))
    .put("spellcasting_ability",entry.getString("spellcasting_ability"))
    .put("source_pointer",row.getString("source_pointer"))
    .put("source_commit",SOURCE_COMMIT)
    .put("auto_rolls",false).put("auto_mutation_allowed",false)
    .put("spell_effects_applied",false).put("spells_cast",0);
  if("will".equals(usage))return out.put("status","available_at_will_pending_casting_rules")
       .put("source_usage_limit",JSONObject.NULL).put("may_attempt",true);
  if("recharge".equals(usage)){
    out.put("minimum_d6",amount).put("recharge_check_required",true);
    if(!in.has("recharge_ready"))return out.put("status","manual_recharge_status_required")
       .put("may_attempt",JSONObject.NULL);
    return out.put("status","recharge_confirmed").put("may_attempt",in.getBoolean("recharge_ready"));
  }
  out.put("source_usage_limit",amount);
  if(!in.has("uses_remaining"))return out.put("status","manual_usage_count_required")
        .put("may_attempt",JSONObject.NULL);
  int left=in.optInt("uses_remaining",-1);
  if(left<0)return blocked("invalid_remaining_uses");
  return out.put("status","use_count_confirmed").put("uses_remaining",left)
       .put("may_attempt",left>0);
 }
 private static JSONObject blocked(String reason)throws Exception{
  return new JSONObject().put("resolved",false).put("reason",reason)
      .put("auto_rolls",false).put("auto_mutation_allowed",false).put("spell_effects_applied",false);
 }
 public static JSONObject coverage()throws Exception {
  return new JSONObject().put("monster_spellcasters",BY_NAME.size())
     .put("source_blob_sha1",SOURCE_SHA).put("source_commit",SOURCE_COMMIT)
     .put("auto_rolls",false).put("full_spell_effect_automation_certified",false);
 }
